	private static void generateTests()
	{
		generateTests(1);
	}

	private static void generateTests(int quantity)
	{
		generateTests(quantity);
	}

	private static void generateTests(int size, int quantity)
	{
		for (int i = 0; i < quantity; i++)
		{
			int[] ints = generateRandomArray(size, -1000, 1000);

			if (ints.length < 3)
			{
				i--;
				continue;
			}

			String input = Arrays.toString(ints).replaceAll("[\\[\\] ]", "");
			boolean expected = isTrionic(ints);

			System.out.printf("MAP.put(new int[]{%s},%s);%n", input, expected);
		}
	}

	// From leetcode solution submission...
	public static boolean isTrionic(int[] A)
	{
		int p = 0, q = 0, n = A.length;
		for (int i = 1; i < n - 1; ++i)
		{
			if (A[i - 1] == A[i])
			{
				return false;
			}
			if (A[i - 1] < A[i] && A[i] > A[i + 1])
			{
				if (p != 0 || q != 0)
				{
					return false;
				}
				p = i;
			}
			if (A[i - 1] > A[i] && A[i] < A[i + 1])
			{
				if (p == 0 || q != 0)
				{
					return false;
				}
				q = i;
			}
		}
		return q > 0;
	}
